tError;{	NSPrintInfo * printInfo = [self printInfo];	NSPrintOperation * printop = [NSPrintOperation printOperationWithView:alignmentView printInfo: printInfo];	return printop;}-(IBAction) saveInputFileAs: (id) sender{	NSSavePanel * thePanel = [NSSavePanel savePanel];	[thePanel setAllowedFileTypes:[NSArray arrayWithObjects:@"csv", nil]];	[thePanel setAllowsOtherFileTypes:NO];	[thePanel setMessage:@"Save input as file ..."];	[thePanel runModal];		NSMutableString * input = [NSMutableString stringWithFormat:@"original, %@\r\r", [self.originalSequence string]];	NJoin * join;	for (join in joins) {		[input appendFormat:@"%@, %@, %@\r", join.jname, join.sequence, join.signal];	}		[input writeToURL:[thePanel URL] atomically:NO encoding: NSUTF8StringEncoding error: NULL];		//if ([thePanel URL]) {	//	[[alignmentView RTFFromRange:NSMakeRange(0, [[alignmentView string] length])] writeToURL:[thePanel URL] atomically:YES];	//}	}-(IBAction) saveAlignmentsAs: (id) sender{	NSSavePanel * thePanel = [NSSavePanel savePanel];	[thePanel setAllowedFileTypes:[NSArray arrayWithObjects:@"rtf", nil]];	[thePanel setAllowsOtherFileTypes:NO];	[thePanel setMessage:@"Save alignments as file ..."];	[thePanel runModalForDirectory:nil file:[alignmentWindow title]];	if ([thePanel URL]) {		[[alignmentView RTFFromRange:NSMakeRange(0, [[alignmentView string] length])] writeToURL:[thePanel URL] atomically:YES];	}}- (NSArray *)joins {    return joins;}- (void)setJoins:(NSArray *)newJoins {	joins = newJoins;}-(IBAction) addJoin: (id) sender {	NJoin * join = [NJoin new];	[join initWithMaker:self];	join.checked = YES;	self.joins = [joins arrayByAddingObject:join];}- (NSString *)windowNibName{    return @"MyDocument";}- (BOOL)writeToURL:(NSURL *)absoluteURL ofType:(NSString *)typeName 			 error:(NSError **)outError{    NSMutableString *csvString = [NSMutableString stringWithString:@"name,sequence,signal,complex,microhomology, micro length, imperfect micro, filler, filler length, filler template, missing left, missing right\r"];     NSEnumerator *pointEnum = [joins objectEnumerator];    NJoin * join;    while ( join = [pointEnum nextObject] ) {        [csvString appendString:[NSString stringWithFormat:@"'%@,'%@,%@,%@,'%@,%@,%@,'%@,%@,%@,%@,%@\r", 								 join.jname, 								 join.sequence, 								 join.signal,								 [NSNumber numberWithBool:join.complexAlignment],								 join.microhomology, 								 join.nmicro, 								 [NSNumber numberWithBool: join.perfectMicro],								 join.filler, 								 join.nfiller,								 [NSNumber numberWithInt: join.fillerTemplate],								 join.nmissingLeft,								 join.nmissingRight]];    }    return [csvString writeToURL:absoluteURL atomically:NO 						encoding:NSUTF8StringEncoding error:outError];}-(void) parseOriginal {	NSString *s = [self.originalSequence string];	NSArray * originalParts = [[self.originalSequence string] componentsSeparatedByString:@"^"];	if (originalParts.count == 2) {		self.leftField = [originalParts objectAtIndex:0];		self.rightField = [originalParts objectAtIndex:1];		self.overhang = @"";	} else if (originalParts.count == 3) {		self.overhang = [originalParts objectAtIndex:1];		self.leftField = [[originalParts objectAtIndex:0] stringByAppendingString:overhang];		self.rightField = [overhang stringByAppendingString:[originalParts objectAtIndex:2]];	} else {		leftField = @"";		rightField = s;		return;	}		NSRange firstCaretRange, secondCaretRange, overhangRange;	firstCaretRange = [[originalSequence string] rangeOfString:@"^"];	secondCaretRange = [[originalSequence string] rangeOfString:@"^" options: NSBackwardsSearch];	overhangRange = [[originalSequence string] rangeOfString:overhang options: 0 range: NSMakeRange(firstCaretRange.location, overhang.length + 1)];	NSMutableAttributedString * ss = [self.originalSequence mutableCopy];	[self refreshPrefs];	NSDictionary * caretFmat = [NSDictionary dictionaryWithObjectsAndKeys: 							  [NSColor redColor], NSForegroundColorAttributeName,								[NSNumber numberWithInt:1], NSStrikethroughStyleAttributeName,								nil];	[ss setAttributes:caretFmat range:firstCaretRange];	[ss setAttributes:caretFmat range:secondCaretRange];	[ss setAttributes:[userPrefs objectForKey:@"overhangFmat"] range:overhangRange];	self.originalSequence = [ss mutableCopy];	}- (BOOL)readFromURL:(NSURL *) absoluteURL ofType:(NSString *) typeName 			  error:(NSError **)outError {    NSString *fileString = [NSString stringWithContentsOfURL:absoluteURL 													encoding:NSUTF8StringEncoding error:outError];	comments = [NSMutableString stringWithCapacity:500]; // clear it;    if ( nil == fileString ) return NO;	NSCharacterSet * skipchars = [NSCharacterSet characterSetWithCharactersInString:@"\n\r\t, "];	NSCharacterSet * linechars = [NSCharacterSet characterSetWithCharactersInString:@"\n\r"];	NSCharacterSet * itemchars = [NSCharacterSet characterSetWithCharactersInString:@"\n\r\t,"];    NSScanner *scanner = [NSScanner scannerWithString:fileString];    [scanner setCharactersToBeSkipped:	 skipchars];    NSMutableArray *newPoints = [NSMutableArray array];	NSString * line;		while ([scanner scanUpToCharactersFromSet:linechars intoString:&line]){		NSString *jname, *sequence, *signalString;				NSScanner * linescanner = [NSScanner scannerWithString:line];		[linescanner setCharactersToBeSkipped:skipchars];				[linescanner scanUpToCharactersFromSet:itemchars intoString:&jname];		[linescanner scanUpToCharactersFromSet:itemchars intoString:&sequence];		signalString = @"-1";		[linescanner scanUpToCharactersFromSet:itemchars intoString:&signalString];		NSRange slashes = [jname rangeOfString:@"//"];				if ([[jname uppercaseString] isEqualToString:@"LEFT"]) {			self.leftField = [sequence copy];		} else if ([[jname uppercaseString] isEqualToString:@"RIGHT"]) {			self.rightField = [sequence copy];					} else if ([[jname uppercaseString] isEqualToString:@"OVERHANG"]) {			self.overhang = [sequence copy];		} else if ([[jname uppercaseString] isEqualToString:@"ORIGINAL"]) {			self.originalSequence = [[NSAttributedString alloc] initWithString: sequence];		} else if (slashes.location < 5) {			// a comment line			[comments appendFormat:@"\r%@\r", line];		} else {			NJoin * join = [NJoin new];			[join initWithMaker: self];			 join.jname = [jname copy];			 join.sequence = [sequence copy];			join.signal = [NSNumber numberWithInt:[signalString intValue]];			if ([join.signal intValue] < 0) {				join.signal = nil;			}			join.checked = YES;			[newPoints addObject: join];		}	}	if (originalSequence.length) {		[self parseOriginal];	} else {		NSString * s = [NSString stringWithFormat:@"%@^%@^%@",								 [leftField substringToIndex:leftField.length - overhang.length],								 overhang,								 [rightField substringFromIndex:overhang.length]];		self.originalSequence = [[NSAttributedString alloc] initWithString: s];		[self parseOriginal];	}if (joins.count < 1) {	    [self setJoins:newPoints];} else {	self.joins = [joins arrayByAddingObjectsFromArray:[newPoints copy]];}    		self.outputTitle = [NSString stringWithFormat:@"alignments for %@", [[absoluteURL path] lastPathComponent]];    return YES;}	-(IBAction) import: (id) sender {	NSOpenPanel * thePanel = [NSOpenPanel openPanel];	[thePanel setTitle:@"Select a text file to open. (Extension = .txt)"];	[thePanel setAllowedFileTypes:[NSArray arrayWithObject:@"txt"]];	[thePanel setAllowsOtherFileTypes:NO];	if ([thePanel runModalForTypes:[NSArray arrayWithObject:@"txt"]] == NSCancelButton) return;	[self readFromURL:[thePanel URL] ofType:@"Document Type" error:NULL];	return;	}-(IBAction) deleteSelected: (id) sender{	NSMutableArray * mJoins = [joins mutableCopy];	NSIndexSet * jSet = [joinsView selectedRowIndexes];	NSUInteger i = [jSet lastIndex];	while (i != NSNotFound) {		[mJoins removeObjectAtIndex:i];		i = [jSet indexLessThanIndex:i];	}	self.joins = [mJoins copy];}	-(IBAction) checkAll: (id) sender	{		NJoin * join;		NSEnumerator * joinEnum = [joins objectEnumerator];		while (join = [joinEnum nextObject]) {			join.checked = YES;		}	}-(IBAction) uncheckAll: (id) sender	{		NJoin * join;		NSEnumerator * joinEnum = [joins objectEnumerator];		while (join = [joinEnum nextObject]) {			join.checked = NO;		}	}-(IBAction) checkSelection: (id) sender{	NJoin * join;	NSIndexSet * jSet = [joinsView selectedRowIndexes];	NSUInteger i = [jSet firstIndex];	while (i != NSNotFound) {		join = [joins objectAtIndex:i];		join.checked = YES;		i = [jSet indexGreaterThanIndex:i];		}}-(IBAction) uncheckSelection: (id) sender{	NJoin * join;	NSIndexSet * jSet = [joinsView selectedRowIndexes];	NSUInteger i = [jSet firstIndex];	while (i != NSNotFound) {		join = [joins objectAtIndex:i];		join.checked = NO;		i = [jSet indexGreaterThanIndex:i];	}}-(IBAction) toggleChecks: (id) sender{	NJoin * join;	NSEnumerator * joinEnum = [joins objectEnumerator];	while (join = [joinEnum nextObject]) {		join.checked = ! join.checked;	}}-(IBAction) toggleSelected: (id) sender{	NJoin * join;	NSIndexSet * jSet = [joinsView selectedRowIndexes];	NSUInteger i = [jSet firstIndex];	while (i != NSNotFound) {		join = [joins objectAtIndex:i];		join.checked = ! join.checked;		i = [jSet indexGreaterThanIndex:i];	}	}-(IBAction) stopModal: (id) sender {	[NSApp stopModalWithCode:3];}-(IBAction) abortModal: (id) sender {	[NSApp abortModal];}-(IBAction) trimSequences: (id) sender {	int stopreason = [[NSApplication sharedApplication] runModalForWindow: trimPanel];	[trimPanel close];	stopreason ++;	int k =  trimLeftFrom ;}-(IBAction) analyze: (id) sender; {	[self refreshPrefs];	[self parseOriginal];	[self appendOutput];	int k = leftField.length;	k = rightField.length;if ((leftField.length < 5) || (rightField.length < 5)) {	[[NSAlert alertWithMessageText:@"Original sequence not well defined" defaultButton:@"Okay" alternateButton:nil otherButton:nil informativeTextWithFormat:@"End-joins cannot be analyzed unless a cut site is indicated. Use a caret (^) to mark the cut site. For staggered cuts, mark both sites with carets."] runModal];	return;}	int i;	NJoin * join;	for(i = 0; i < joins.count; i ++) {		join = [joins objectAtIndex:i];		if (join.checked && (join.sequence.length > 5)) {			[join doAlign];		}	}	[alignmentWindow setTitle:[NSString stringWithFormat:@"Analysis for %@", [[mainWindow title] stringByDeletingPathExtension]]];}-(void) appendOutputA: (NSAttributedString*) theString{	[outputStorage replaceCharactersInRange: NSMakeRange(outputStorage.length, 0) withAttributedString:theString];	[alignmentView scrollRangeToVisible:NSMakeRange(outputStorage.length, 0)];}-(void) appendOutput: (NSString *) theString{	[outputStorage replaceCharactersInRange: NSMakeRange(outputStorage.length, 0) withString:theString];	[alignmentView scrollRangeToVisible:NSMakeRange(outputStorage.length, 0)];}-(void) appendOutput; // if no string is given then 'output' will be used;{	[self appendOutput: output];	output = [NSMutableString stringWithCapacity:500]; // clear it;}- (void)windowControllerDidLoadNib:(NSWindowController *) aController{    [super windowControllerDidLoadNib:aController];    // Add any code here that needs to be executed once the windowController has loaded the document's window.}- (NSData *)dataOfType:(NSString *)typeName error:(NSError **)outError{    // Insert code here to write your document to data of the specified type. If the given outError != NULL, ensure that you set *outError when returning nil.    // You can also choose to override -fileWrapperOfType:error:, -writeToURL:ofType:error:, or -writeToURL:ofType:forSaveOperation:originalContentsURL:error: instead.    // For applications targeted for Panther or earlier systems, you should use the deprecated API -dataRepresentationOfType:. In this case you can also choose to override -fileWrapperRepresentationOfType: or -writeToFile:ofType: instead.    if ( outError != NULL ) {		*outError = [NSError errorWithDomain:NSOSStatusErrorDomain code:unimpErr userInfo:NULL];	}	return nil;}- (BOOL)readFromData:(NSData *)data ofType:(NSString *)typeName error:(NSError **)outError{    // Insert code here to read your document from the given data of the specified type.  If the given outError != NULL, ensure that you set *outError when returning NO.    // You can also choose to override -readFromFileWrapper:ofType:error: or -readFromURL:ofType:error: instead.         // For applications targeted for Panther or earlier systems, you should use the deprecated API -loadDataRepresentation:ofType. In this case you can also choose to override -readFromFile:ofType: or -loadFileWrapperRepresentation:ofType: instead.        if ( outError != NULL ) {		*outError = [NSError errorWithDomain:NSOSStatusErrorDomain code:unimpErr userInfo:NULL];	}    return YES;}-(void) addJoinFromURL: (NSURL *) url {	NSData * fileData = [NSData dataWithContentsOfURL:url];	NSString * upath = [url path];	char * t = (char *) fileData.bytes;	NSString * extension = [upath pathExtension];	if (![extension isEqualToString:@"ab1"]) return;		struct DirEntry * dird, dir;	dird =  (struct DirEntry *) (t+6);	dir = *dird;	int nentries = Endian32_Swap(dir.numelements);	dird =  (struct DirEntry *) (t + Endian32_Swap(dir.dataoffset));	int i, j, k, ii, Ncount, seqlength, numNs;	char * seq;	short * shp, sh;	NSString * first;	NSMutableData * seqData;	for (i = 0; i < nentries; i++) {		dir = dird[i];		if ((dir.name == PBAS) && (Endian32_Swap(dir.number) == 1)) // PBAS #1		{			k = Endian32_Swap(dir.dataoffset);			seq = t+k;			seqlength = Endian32_Swap(dir.datasize);			seqData = [[NSData dataWithBytes:seq length:seqlength+1] mutableCopy];			seq = seqData.mutableBytes;						// trim trailing Ns			j = seqlength; Ncount = 0;			     //  Get initial count			for (ii = 0; ii < Nwindow; ii++) {				if (seq[j - ii] == enChar) {					Ncount ++;				}			}			      //  Keep replacing with 0's until there are no more than Nmax N's in a window of Nwindow bases			while ((j > Nwindow) && (Ncount > Nmax)) {				if(seq[j] == enChar) Ncount --;				if(seq[j - Nwindow] == enChar) Ncount++;				seq[j--] = 0;			}			seq[seqlength] = 0;			first = [NSString stringWithUTF8String:seq];		}				// Get the average signal strength of the four bases		if ((dir.name == SslashNpercent) && (Endian32_Swap(dir.number) == 1)) // S/N% #1		{			k = Endian32_Swap(dir.dataoffset);			shp = (short *) (t + k);			sh = Endian16_Swap(*shp);			sh += Endian16_Swap(shp[1]);			sh += Endian16_Swap(shp[2]);			sh += Endian16_Swap(shp[3]);			sh /= 4;		}	}	NJoin * join = [NJoin new];	[join initWithMaker:self];	join.checked = YES;	join.sequence = first;	join.signal = [NSNumber numberWithInt:sh];	join.jname = [[[url path] lastPathComponent] stringByDeletingPathExtension];	self.joins = [joins arrayByAddingObject:join];	}-(IBAction) read1ABIfile: (id) sender {	NSOpenPanel * thePanel = [NSOpenPanel openPanel];	[thePanel setTitle:@"Select an ABI file to open. (Extension = .ab1)"];	[thePanel setAllowedFileTypes:[NSArray arrayWithObject:@"ab1"]];	[thePanel setAllowsOtherFileTypes:NO];	if ([thePanel runModalForTypes:[NSArray arrayWithObject:@"ab1"]] == NSCancelButton) return;	[self addJoinFromURL: [[thePanel URLs] objectAtIndex:0]];	return;	}-(IBAction) readABIfolder: (id) sender {	NSOpenPanel * thePanel = [NSOpenPanel openPanel];	[thePanel setTitle:@"Select a folder to open."];	//[thePanel setAllowedFileTypes:[NSArray arrayWithObject:@"ab1"]];	[thePanel setAllowsOtherFileTypes:NO];	[thePanel setCanChooseFiles:NO];	[thePanel setCanChooseDirectories:YES];	if ([thePanel runModal] == NSCancelButton) return;	NSString *pname, *dpath;	dpath = [[[thePanel URLs] objectAtIndex: 0] path];	NSDirectoryEnumerator *direnum = [[NSFileManager defaultManager]									  enumeratorAtPath:dpath];	int scount = 1;	NSURL * furl;	while (pname = [direnum nextObject])	{		if ([[pname pathExtension] isEqualToString:@"ab1"] && scount < 300)		{			furl = [NSURL fileURLWithPath:[NSString stringWithFormat:@"%@/%@", dpath, pname] ];			[self addJoinFromURL:furl];			scount++;					}	}		return;	}-(IBAction) trySomething: (id) sender {	NSOpenPanel * thePanel = [NSOpenPanel openPanel];	[thePanel setTitle:@"Select an ABI file to open. (Extension = .ab1)"];	[thePanel setAllowedFileTypes:[NSArray arrayWithObject:@"ab1"]];	[thePanel setAllowsOtherFileTypes:NO];	if ([thePanel runModalForTypes:[NSArray arrayWithObject:@"ab1"]] == NSCancelButton) return;	[self addJoinFromURL: [[thePanel URLs] objectAtIndex:0]];	 return;	 }@end